/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'tipoajusteww_Execute') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Tipos de Ajustes do Estoque"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'TIPAJUNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &tipajuNome1.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltertipajuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FiltertipajuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &tipajuNome = &tipajuNome1 print printBlockFiltertipajuNome EndIf Case &DynamicFiltersSelector1 = !'TIPAJUSIGLA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &tipajuSigla1.FromString(&GridStateDynamicFilter.Value) If not &tipajuSigla1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltertipajuSiglaDescription = format('%1 (%2)', "Sigla", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FiltertipajuSiglaDescription = format('%1 (%2)', "Sigla", "WWP_FilterContains") EndCase &tipajuSigla = &tipajuSigla1 print printBlockFiltertipajuSigla EndIf Case &DynamicFiltersSelector1 = !'TIPAJUACAO' &tipajuAcao1.FromString(&GridStateDynamicFilter.Value) If not &tipajuAcao1.IsEmpty() &FiltertipajuAcao1ValueDescription = &tipajuAcao1.EnumerationDescription()
&FiltertipajuAcaoValueDescription = &FiltertipajuAcao1ValueDescription print printBlockFiltertipajuAcao EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'TIPAJUNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &tipajuNome2.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltertipajuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FiltertipajuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &tipajuNome = &tipajuNome2 print printBlockFiltertipajuNome EndIf Case &DynamicFiltersSelector2 = !'TIPAJUSIGLA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &tipajuSigla2.FromString(&GridStateDynamicFilter.Value) If not &tipajuSigla2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltertipajuSiglaDescription = format('%1 (%2)', "Sigla", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FiltertipajuSiglaDescription = format('%1 (%2)', "Sigla", "WWP_FilterContains") EndCase &tipajuSigla = &tipajuSigla2 print printBlockFiltertipajuSigla EndIf Case &DynamicFiltersSelector2 = !'TIPAJUACAO' &tipajuAcao2.FromString(&GridStateDynamicFilter.Value) If not &tipajuAcao2.IsEmpty() &FiltertipajuAcao2ValueDescription = &tipajuAcao2.EnumerationDescription()
&FiltertipajuAcaoValueDescription = &FiltertipajuAcao2ValueDescription print printBlockFiltertipajuAcao EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'TIPAJUNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &tipajuNome3.FromString(&GridStateDynamicFilter.Value) If not &tipajuNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltertipajuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FiltertipajuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &tipajuNome = &tipajuNome3 print printBlockFiltertipajuNome EndIf Case &DynamicFiltersSelector3 = !'TIPAJUSIGLA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &tipajuSigla3.FromString(&GridStateDynamicFilter.Value) If not &tipajuSigla3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltertipajuSiglaDescription = format('%1 (%2)', "Sigla", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FiltertipajuSiglaDescription = format('%1 (%2)', "Sigla", "WWP_FilterContains") EndCase &tipajuSigla = &tipajuSigla3 print printBlockFiltertipajuSigla EndIf Case &DynamicFiltersSelector3 = !'TIPAJUACAO' &tipajuAcao3.FromString(&GridStateDynamicFilter.Value) If not &tipajuAcao3.IsEmpty() &FiltertipajuAcao3ValueDescription = &tipajuAcao3.EnumerationDescription()
&FiltertipajuAcaoValueDescription = &FiltertipajuAcao3ValueDescription print printBlockFiltertipajuAcao EndIf EndCase EndIf EndIf EndIf If not (&TFtipajuCodigo.IsEmpty() AND &TFtipajuCodigo_To.IsEmpty()) print printBlockTFtipajuCodigo &TFtipajuCodigo_To_Description = format('%1 (%2)', "Ajuste", "WWP_TSTo") print printBlockTFtipajuCodigo_To EndIf If not &TFtipajuNome_Sel.IsEmpty() print printBlockTFtipajuNome_Sel Else If not &TFtipajuNome.IsEmpty() print printBlockTFtipajuNome EndIf EndIf If not &TFtipajuSigla_Sel.IsEmpty() print printBlockTFtipajuSigla_Sel Else If not &TFtipajuSigla.IsEmpty() print printBlockTFtipajuSigla EndIf EndIf &TFtipajuAcao_Sels.FromJson(&TFtipajuAcao_SelsJson) If not &TFtipajuAcao_Sels.Count = 0 &i = 1 For &TFtipajuAcao_Sel in &TFtipajuAcao_Sels If &i = 1 &TFtipajuAcao_SelDscs = '' Else &TFtipajuAcao_SelDscs += ', ' EndIf &FilterTFtipajuAcao_SelValueDescription = &TFtipajuAcao_Sel.EnumerationDescription()
&TFtipajuAcao_SelDscs += &FilterTFtipajuAcao_SelValueDescription &i += 1 EndFor print printBlockTFtipajuAcao_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each TipoAjuste order tipajuNome when &OrderedBy = 1 AND &OrderedDsc = False order (tipajuNome) when &OrderedBy = 1 AND &OrderedDsc = True order tipajuCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (tipajuCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order tipajuSigla when &OrderedBy = 3 AND &OrderedDsc = False order (tipajuSigla) when &OrderedBy = 3 AND &OrderedDsc = True order tipajuAcao when &OrderedBy = 4 AND &OrderedDsc = False order (tipajuAcao) when &OrderedBy = 4 AND &OrderedDsc = True
using TipoAjusteWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &tipajuNome1, &tipajuSigla1, &tipajuAcao1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &tipajuNome2, &tipajuSigla2, &tipajuAcao2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &tipajuNome3, &tipajuSigla3, &tipajuAcao3, &TFtipajuCodigo , &TFtipajuCodigo_To, &TFtipajuNome, &TFtipajuNome_Sel, &TFtipajuSigla, &TFtipajuSigla_Sel, &TFtipajuAcao_Sels) Where prefCodigo = &prefCodigo &tipajuAcaoDescription = tipajuAcao.EnumerationDescription()
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"TipoAjusteWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"TipoAjusteWWGridState")) Else &GridState.FromXml(&Session.Get(!"TipoAjusteWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFTIPAJUCODIGO" &TFtipajuCodigo.FromString(&GridStateFilterValue.Value) &TFtipajuCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFTIPAJUNOME" &TFtipajuNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUNOME_SEL" &TFtipajuNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUSIGLA" &TFtipajuSigla.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUSIGLA_SEL" &TFtipajuSigla_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFTIPAJUACAO_SEL" &TFtipajuAcao_SelsJson = &GridStateFilterValue.Value &TFtipajuAcao_Sels.FromJson(&TFtipajuAcao_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforePrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
